from ...base.client import BaseClient
from ....client.decorators import api_version_check


class ArchiveMethods(BaseClient):
    """
    Методы группы 'Архив' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=112)
    async def rapi_archive_chatsModify(self, add_chats: list[str] = (), del_chats: list[str] = ()):
        """
        Добавляет/удаляет чаты в Архиве
        На изменение Архива рассылается событие archive, содержащие версию содержимого Архива (см. /bos/fetchEvents)
        В ответе метода содержится новая версия содержимого Архива - contentVersion
        Порядок ответа на запрос и генерации события не гарантирована
        После каждого успешного изменения содержимого архива его contentVersion увеличивается на 1
        После получения ответа с кодом 20000 клиенту стоит сравнить его contentVersion и contentVersion в ответе,
        и если версия в ответе отличается больше чем на 1 - нужно запросить
        актуальное содержимое Архива с помощью getContent
        """
        params = {}
        if add_chats:
            params["addChats"] = add_chats
        if del_chats:
            params["delChats"] = del_chats

        return await self.post(
            "rapi/archive/chatsModify",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": params,
            },
        )

    @api_version_check(min_version=123)
    async def rapi_archive_chatPin(self, chat_id: str, pin: bool = True):
        """
        Добавляем или снимаем пин с чата в архиве
        """
        return await self.post(
            "rapi/archive/chatPin",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"chat": chat_id, "pin": pin},
            },
        )

    @api_version_check(min_version=123)
    async def rapi_archive_changePinsOrder(self, pins: list[str]):
        """
        Расставляет запиненные чаты в архиве в указанном порядке
        На изменение Архива рассылается событие archive, содержащие версию содержимого Архива (см. /bos/fetchEvents)
        """
        return await self.post(
            "rapi/archive/changePinsOrder",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"pins": pins},
            },
        )

    @api_version_check(min_version=112)
    async def rapi_archive_getContent(self):
        """
        Возвращает списки чатов и пинов Архива.
        Списки чатов и пинов в папке также присылается в порядке добавления клиентом.
        Списки чатов и пинов могут содержать одни и те же значения.
        """
        return await self.post(
            "rapi/archive/getContent",
            json={"reqId": self.getReqId(), "aimsid": self.aimsid},
        )
